func (this *Bullish) HandleTrades(client ccxt.ClientInterface, message map[string]any) {
	//
	//     {
	//         "type": "snapshot",
	//         "dataType": "V1TAAnonymousTradeUpdate",
	//         "data": {
	//             "trades": [
	//                 {
	//                     "tradeId": "100086000000609304",
	//                     "isTaker": true,
	//                     "price": "104889.2063",
	//                     "createdAtTimestamp": "1749124509118",
	//                     "quantity": "0.01000000",
	//                     "publishedAtTimestamp": "1749124531466",
	//                     "side": "BUY",
	//                     "createdAtDatetime": "2025-06-05T11:55:09.118Z",
	//                     "symbol": "BTCUSDC"
	//                 }
	//             ],
	//             "createdAtTimestamp": "1749124509118",
	//             "publishedAtTimestamp": "1749124531466",
	//             "symbol": "BTCUSDC"
	//         }
	//     }
	//
	var data, _ = message["data"].(map[string]any)
	var marketId *string = this.SafeString(data, "symbol")
	var symbol *string = this.SafeSymbol(marketId)
	if symbol == nil {
		return
	}
	var market map[string]any = this.Market(symbol)
	var rawTrades []any
	rawTrades, _ = data["trades"].([]any)
	if rawTrades == nil {
		rawTrades = []any{}
	}
	var trades []any = this.ParseTrades(rawTrades, market)
	if _, ok := this.Trades[*symbol]; !ok {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		tradesArrayCache := ccxt.NewArrayCache(limit)
		this.Trades[*symbol] = tradesArrayCache
	}
	var tradesArray ccxt.WsArrayCache = this.Trades[*symbol]
	var tradesList []any = this.ToArray(trades)
	for i := 0; i < len(tradesList); i++ {
		tradesArray.Append(tradesList[i])
	}
	this.Trades[*symbol] = tradesArray
	var messageHash string = "trades::" + *this.SafeString(market, "symbol", "")
	client.Resolve(tradesArray, messageHash)
}

