func (this *Bullish) HandleOrderBook(client ccxt.ClientInterface, message map[string]any) {
	//
	//     {
	//         "type": "snapshot",
	//         "dataType": "V1TALevel2",
	//         "data": {
	//             "timestamp": "1749372632028",
	//             "bids": [
	//                 "105523.3000",
	//                 "0.00046045",
	//             ],
	//             "asks": [
	//                 "105523.4000",
	//                 "0.00117112",
	//             ],
	//             "publishedAtTimestamp": "1749372632073",
	//             "datetime": "2025-06-08T08:50:32.028Z",
	//             "sequenceNumberRange": [ 1967862061, 1967862062 ],
	//             "symbol": "BTCUSDC"
	//         }
	//     }
	//
	// current channel is 'l2Orderbook' which returns only snapshots
	var data, _ = message["data"].(map[string]any)
	var marketId *string = this.SafeString(data, "symbol")
	var symbol *string = this.SafeSymbol(marketId)
	var messageHash string = "orderbook::" + *symbol
	var timestamp *int64 = this.SafeInteger(data, "timestamp")
	if !(symbol != nil && this.Orderbooks[*symbol] != nil) {
		if symbol != nil {
			this.Orderbooks[*symbol] = this.OrderBook()
		}
	}
	var orderbook ccxt.OrderBookInterface = this.Orderbooks[*symbol]
	var bids []any = this.SeparateBidsOrAsks(this.SafeList(data, "bids", []any{}))
	var asks []any = this.SeparateBidsOrAsks(this.SafeList(data, "asks", []any{}))
	var snapshot map[string]any = map[string]any{
		"bids": bids,
		"asks": asks,
	}
	var parsed map[string]any = this.ParseOrderBook(snapshot, symbol, timestamp)
	var sequenceNumberRange, _ = data["sequenceNumberRange"].([]any)
	var sequenceNumberRangeLength int = len(sequenceNumberRange)
	if sequenceNumberRangeLength > 0 {
		var lastIndex int64 = int64(sequenceNumberRangeLength) - 1
		parsed["nonce"] = this.SafeInteger(sequenceNumberRange, lastIndex)
	}
	orderbook.Reset(parsed)
	if symbol != nil {
		this.Orderbooks[*symbol] = orderbook
	}
	client.Resolve(orderbook, messageHash)
}
func (this *Bullish) SeparateBidsOrAsks(entry any) []any {
	var result []any = []any{}
	// 300 = '54885.0000000'
	// 301 = '0.06141566'
	// 302 ='53714.0000000'
	var entries []any = this.ToArray(entry)
	for i := 0; i < len(entries); i++ {
		if i%2 != 0 {
			continue
		}
		var price *string = this.SafeString(entries, i)
		result = append(result, []any{price, this.SafeString(entries, i+1)})
	}
	return result
}

