func (this *Bullish) HandleOrders(client ccxt.ClientInterface, message map[string]any) {
	// snapshot
	//     {
	//         "type": "snapshot",
	//         "tradingAccountId": "111309424211255",
	//         "dataType": "V1TAOrder",
	//         "data": [ ... ] // could be an empty list or a list of orders
	//     }
	//
	// update
	//     {
	//         "type": "update",
	//         "tradingAccountId": "111309424211255",
	//         "dataType": "V1TAOrder",
	//         "data": {
	//             "status": "OPEN",
	//             "createdAtTimestamp": "1751893427971",
	//             "quoteFee": "0.000000",
	//             "stopPrice": null,
	//             "quantityFilled": "0.00000000",
	//             "handle": null,
	//             "clientOrderId": null,
	//             "quantity": "0.10000000",
	//             "margin": false,
	//             "side": "BUY",
	//             "createdAtDatetime": "2025-07-07T13:03:47.971Z",
	//             "isLiquidation": false,
	//             "borrowedQuoteQuantity": null,
	//             "borrowedBaseQuantity": null,
	//             "timeInForce": "GTC",
	//             "borrowedQuantity": null,
	//             "baseFee": "0.000000",
	//             "quoteAmount": "0.0000000",
	//             "price": "0.0000000",
	//             "statusReason": "Order accepted",
	//             "type": "MKT",
	//             "statusReasonCode": 6014,
	//             "allowBorrow": false,
	//             "orderId": "862317981870850049",
	//             "publishedAtTimestamp": "1751893427975",
	//             "symbol": "ETHUSDT",
	//             "averageFillPrice": null
	//         }
	//     }
	//
	var typeVar *string = this.SafeString(message, "type")
	var rawOrders []any = []any{}
	if typeVar != nil && *typeVar == "update" {
		var data map[string]any
		data, _ = message["data"].(map[string]any)
		if data == nil {
			data = map[string]any{}
		}
		rawOrders = append(rawOrders, data) // update is a single order
	} else {
		rawOrders, _ = message["data"].([]any)
		if rawOrders == nil {
			rawOrders = []any{}
		} // snapshot is a list of orders
	}
	var numRawOrders int = len(rawOrders) // hoisted - inline .length within conditionals becomes strlen for php, fatal on arrays
	if numRawOrders > 0 {
		if this.Orders == nil {
			var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
			this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
		}
		var orders ccxt.WsArrayCache = this.Orders
		var symbols map[string]any = map[string]any{}
		for i := 0; i < len(rawOrders); i++ {
			rawOrdersDict67453, _ := rawOrders[i].(map[string]any)
			if rawOrdersDict67453 == nil {
				rawOrdersDict67453 = map[string]any{}
			}
			var parsedOrder map[string]any = ccxt.OrderToMap(this.ParseOrder(rawOrdersDict67453))
			orders.Append(parsedOrder)
			var symbol *string = this.SafeString(parsedOrder, "symbol")
			if symbol != nil {
				symbols[*symbol] = true
			}
		}
		var messageHash string = "orders"
		client.Resolve(orders, messageHash)
		var keys []string = nil
		if symbols != nil {
			keys = make([]string, 0, len(symbols))
			for objectKey := range symbols {
				keys = append(keys, objectKey)
			}
		}
		for i := 0; i < len(keys); i++ {
			var hashSymbol string = keys[i]
			var symbolMessageHash string = messageHash + "::" + hashSymbol
			client.Resolve(this.Orders, symbolMessageHash)
		}
	}
}

